package com.bank.risk;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.util.Deque;

// A stack of balances that also returns the minimum in O(1).
public class BalanceMinStack {

    private final Deque<BigDecimal> mainStack = new ArrayDeque<>();
    private final Deque<BigDecimal> minStack = new ArrayDeque<>();

    // Push a balance; record the running minimum in lockstep.
    public void push(BigDecimal value) {
        mainStack.push(value);
        BigDecimal currentMin = minStack.isEmpty()
                ? value
                : (value.compareTo(minStack.peek()) < 0 ? value : minStack.peek());
        minStack.push(currentMin);
    }

    // Pop both stacks together to keep the minimum correct.
    public BigDecimal pop() {
        if (mainStack.isEmpty()) {
            throw new IllegalStateException("Cannot pop an empty balance stack");
        }
        minStack.pop();
        return mainStack.pop();
    }

    // The current balance on top.
    public BigDecimal top() {
        if (mainStack.isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return mainStack.peek();
    }

    // The minimum of all balances currently in the stack — O(1).
    public BigDecimal getMin() {
        if (minStack.isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return minStack.peek();
    }

    public boolean isEmpty() {
        return mainStack.isEmpty();
    }
}
