package com.bank.risk;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Uses the min stack to monitor the lowest intraday balance.
public class RiskMonitorService {

    private static final Logger log = Logger.getLogger(RiskMonitorService.class.getName());
    private final BalanceMinStack balances = new BalanceMinStack();

    public void recordBalance(BigDecimal balance) {
        balances.push(balance);
        log.info(() -> "Recorded balance " + balance
                + " | lowest so far = " + balances.getMin());
    }

    public void reverseLast() {
        BigDecimal removed = balances.pop();
        if (balances.isEmpty()) {
            log.warning(() -> "Reversed " + removed + " | no balances remain");
        } else {
            log.info(() -> "Reversed " + removed
                    + " | lowest so far = " + balances.getMin());
        }
    }
}
