package com.bank.risk;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MinStackDemo {

    private static final Logger log = Logger.getLogger(MinStackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Intraday Balance Risk Monitor (SAV2001)");
        RiskMonitorService monitor = new RiskMonitorService();

        monitor.recordBalance(new BigDecimal("1000000"));
        monitor.recordBalance(new BigDecimal("850000"));
        monitor.recordBalance(new BigDecimal("920000"));
        monitor.recordBalance(new BigDecimal("600000")); // new low
        monitor.reverseLast();                            // undo 600000
        monitor.recordBalance(new BigDecimal("700000"));
    }
}
